-- ============================================================
-- CYBER CHALLENGE - Dump inicial do banco (schema + dados)
-- ============================================================
-- Banco: MySQL 8.0+
--
-- O Cyber Challenge possui um sistema de contas simples: nickname (unico),
-- idade, autoavaliacao e senha (armazenada apenas como hash BCrypt -- este
-- dump nunca contem nenhuma conta pronta, ja que isso exigiria gravar um
-- hash de senha real em um arquivo versionado).
--
-- Modelo de dados: "participantes" guarda a conta (nickname/idade/
-- autoavaliacao/senha_hash); cada jogada completa de 10 perguntas gera um
-- registro em "partidas" (nivel, pontuacao, acertos, erros, tempos, nota
-- final), referenciando o participante por chave estrangeira. O ranking
-- sempre filtra por nivel a partir da tabela "partidas".
--
-- Como usar (opcional -- a aplicacao tambem popula o estoque de perguntas
-- sozinha automaticamente na primeira execucao, caso a tabela esteja
-- vazia; "participantes" e "partidas" comecam sempre vazias, criadas
-- organicamente pelo cadastro/uso do jogo):
--
--   mysql -u root -p < sql/cyberchallenge_dump.sql
--
-- Isso cria o banco "cyberchallenge", todas as tabelas usadas pela
-- aplicacao e ja insere o estoque completo de 401 perguntas (240
-- Verdadeiro/Falso + 41 de multipla escolha + 120 de completar a frase,
-- com suas alternativas).
-- ============================================================

CREATE DATABASE IF NOT EXISTS cyberchallenge
    CHARACTER SET utf8mb4
    COLLATE utf8mb4_unicode_ci;

USE cyberchallenge;

-- ------------------------------------------------------------
-- Tabela: participantes (conta -- nickname unico + senha com hash)
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS participantes (
    id               BIGINT NOT NULL AUTO_INCREMENT,
    nickname         VARCHAR(30) NOT NULL,
    idade            INT NULL,
    autoavaliacao    INT NULL,
    senha_hash       VARCHAR(255) NOT NULL,
    data_cadastro    DATETIME NOT NULL,
    PRIMARY KEY (id),
    UNIQUE KEY uk_participantes_nickname (nickname)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------
-- Tabela: perguntas
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS perguntas (
    id                 BIGINT NOT NULL AUTO_INCREMENT,
    texto              TEXT NOT NULL,
    tema               VARCHAR(255) NOT NULL,
    resposta_correta   TINYINT(1) NULL,
    explicacao         TEXT NOT NULL,
    ativa              TINYINT(1) NOT NULL DEFAULT 1,
    nivel              INT NOT NULL,
    tipo               VARCHAR(20) NOT NULL DEFAULT 'VERDADEIRO_FALSO',
    PRIMARY KEY (id),
    KEY idx_perguntas_nivel_ativa (nivel, ativa)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------
-- Tabela: alternativas (opcoes de multipla escolha e completar a frase)
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS alternativas (
    id            BIGINT NOT NULL AUTO_INCREMENT,
    pergunta_id   BIGINT NOT NULL,
    texto         TEXT NOT NULL,
    correta       TINYINT(1) NOT NULL DEFAULT 0,
    PRIMARY KEY (id),
    KEY idx_alternativas_pergunta (pergunta_id),
    CONSTRAINT fk_alternativas_pergunta FOREIGN KEY (pergunta_id) REFERENCES perguntas (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------
-- Tabela: partidas (uma jogada completa de 10 perguntas)
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS partidas (
    id                  BIGINT NOT NULL AUTO_INCREMENT,
    participante_id     BIGINT NOT NULL,
    data_partida        DATETIME NOT NULL,
    nivel               INT NOT NULL,
    pontuacao           INT NOT NULL,
    acertos             INT NOT NULL,
    erros               INT NOT NULL,
    tempo_total         DOUBLE NULL,
    tempo_medio         DOUBLE NULL,
    nota_final          DOUBLE NOT NULL,
    PRIMARY KEY (id),
    KEY idx_partidas_nivel (nivel),
    CONSTRAINT fk_partidas_participante FOREIGN KEY (participante_id) REFERENCES participantes (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------
-- Tabela: respostas
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS respostas (
    id                          BIGINT NOT NULL AUTO_INCREMENT,
    partida_id                  BIGINT NOT NULL,
    pergunta_id                 BIGINT NOT NULL,
    resposta                    TINYINT(1) NULL,
    alternativa_escolhida_id    BIGINT NULL,
    correta                     TINYINT(1) NOT NULL,
    tempo_resposta              DOUBLE NOT NULL,
    data_resposta               DATETIME NOT NULL,
    PRIMARY KEY (id),
    KEY idx_respostas_partida (partida_id),
    KEY idx_respostas_pergunta (pergunta_id),
    CONSTRAINT fk_respostas_partida FOREIGN KEY (partida_id) REFERENCES partidas (id),
    CONSTRAINT fk_respostas_pergunta FOREIGN KEY (pergunta_id) REFERENCES perguntas (id),
    CONSTRAINT fk_respostas_alternativa FOREIGN KEY (alternativa_escolhida_id) REFERENCES alternativas (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------
-- Dados: estoque de perguntas (240 Verdadeiro/Falso + 41 multipla escolha
-- + 120 completar a frase = 401 perguntas)
-- (mesmo conteudo de src/main/resources/seed/*.json)
-- ------------------------------------------------------------

-- ------------------------------------------------------------
-- Dados: alternativas das perguntas de multipla escolha e completar a frase
-- ------------------------------------------------------------
